import { createHash } from "node:crypto";
import { SubsidiaryHumanCapitalMetricId as M, type SubsidiaryHumanCapitalMetricDocument, type SubsidiaryHumanCapitalNoteProof } from "../../src/index";
export const tags = { [M.FemaleManagerRatio]: "RatioOfFemaleEmployeesInManagerialPositionsMetricsOfConsolidatedSubsidiaries",
    [M.MaleChildcareLeaveAllRatio]: "AllEmployeesRatioOfMaleEmployeesTakingChildcareLeaveMetricsOfConsolidatedSubsidiaries", [M.MaleChildcareLeaveRegularRatio]: "RegularEmployeesRatioOfMaleEmployeesTakingChildcareLeaveMetricsOfConsolidatedSubsidiaries", [M.MaleChildcareLeaveNonRegularRatio]: "NonRegularEmployeesRatioOfMaleEmployeesTakingChildcareLeaveMetricsOfConsolidatedSubsidiaries",
    [M.GenderWageAllRatio]: "AllEmployeesDifferencesInWagesBetweenMaleAndFemaleEmployeesMetricsOfConsolidatedSubsidiaries", [M.GenderWageRegularRatio]: "RegularEmployeesDifferencesInWagesBetweenMaleAndFemaleEmployeesMetricsOfConsolidatedSubsidiaries", [M.GenderWageNonRegularRatio]: "NonRegularEmployeesDifferencesInWagesBetweenMaleAndFemaleEmployeesMetricsOfConsolidatedSubsidiaries" };
const note = "合成注記。算出方法と対象者不在の説明を呼出元が確認。";
export const proof: SubsidiaryHumanCapitalNoteProof = { key: "jpcrp_cor:InformationAboutEmployeesTextBlock", contextRef: "filing", rawSha256: createHash("sha256").update(note).digest("hex") };
export const numeric = (tag: string, raw: string | null, row = 1, attrs = "") => `<jpcrp_cor:${tag} contextRef="row${row}" unitRef="ratio" decimals="INF" ${raw === null ? 'xsi:nil="true"' : ""} ${attrs}>${raw ?? ""}</jpcrp_cor:${tag}>`;
export function subsidiaryDocument(docID = "DOC-A", rows: { name: string; values?: Partial<Record<M, string | null | undefined>> }[] = [{ name: "合成子会社" }], extra = ""): SubsidiaryHumanCapitalMetricDocument {
    const c = (id: string, instant: string, row?: number) => `<xbrli:context id="${id}"><xbrli:entity><xbrli:identifier scheme="synthetic">${docID}</xbrli:identifier></xbrli:entity><xbrli:period><xbrli:instant>${instant}</xbrli:instant></xbrli:period>${row ? `<xbrli:scenario><xbrldi:explicitMember dimension="jpcrp_cor:SequentialNumbersAxis">jpcrp_cor:Row${row}Member</xbrldi:explicitMember></xbrli:scenario>` : ""}</xbrli:context>`;
    const defaults = { [M.FemaleManagerRatio]: "0.1", [M.MaleChildcareLeaveAllRatio]: "1.2", [M.MaleChildcareLeaveRegularRatio]: "1", [M.MaleChildcareLeaveNonRegularRatio]: "0", [M.GenderWageAllRatio]: "0.75", [M.GenderWageRegularRatio]: "0.8", [M.GenderWageNonRegularRatio]: "0.6" };
    const xml = `<xbrli:xbrl xmlns:xbrli="http://www.xbrl.org/2003/instance" xmlns:xbrldi="http://xbrl.org/2006/xbrldi" xmlns:jpcrp_cor="http://disclosure.edinet-fsa.go.jp/taxonomy/jpcrp/2025-11-01/jpcrp_cor" xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance">` +
        c("filing", "2026-06-24") + rows.map((_r, i) => c(`row${i+1}`, "2026-03-31", i+1)).join("") + '<xbrli:unit id="ratio"><xbrli:measure>xbrli:pure</xbrli:measure></xbrli:unit>' +
        `<${proof.key} contextRef="filing">${note}</${proof.key}>` + rows.map((row, i) => `<jpcrp_cor:ConsolidatedSubsidiariesMetricsOfConsolidatedSubsidiaries contextRef="row${i+1}">${row.name}</jpcrp_cor:ConsolidatedSubsidiariesMetricsOfConsolidatedSubsidiaries>` + Object.entries({ ...defaults, ...row.values }).filter(([_k, v]) => v !== undefined).map(([id, value]) => numeric(tags[id as M], value!, i+1)).join("")).join("") + extra + '</xbrli:xbrl>';
    return { xml, metadata: { docID, instant: "2026-03-31" } };
}
